llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C51"],
      "claim": "Vismodegib, the highest-transfer analogue (0.8506), has a measured absolute oral bioavailability of 31.8% in humans after a 150 mg dose, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Guanfacine, with a high transfer score of 0.8029, shows an absolute oral bioavailability of about 80% in healthy volunteers, well above the threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Dasatinib, a kinase inhibitor with a transfer score of 0.7559, has an absolute oral bioavailability of 34% in humans despite first-pass metabolism, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C78"],
      "claim": "Bosentan, transfer score 0.7323, has an absolute oral bioavailability of 50% in humans, supporting the high category.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C65"],
      "claim": "Sildenafil, transfer score 0.6946, has an absolute oral bioavailability of 38% from an oral versus intravenous comparison, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Erlotinib, transfer score 0.575, has a median absolute oral bioavailability of 76% in cancer patients, strongly supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C73"],
      "claim": "GSK269984A, transfer score 0.5736, showed absolute oral bioavailability in excess of 94% in humans, supporting high bioavailability.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The preponderance of transferable experimental evidence, led by vismodegib (31.8% absolute F) and supported by dasatinib, bosentan, sildenafil, erlotinib, guanfacine, and GSK269984A, indicates that the query is more likely than not to have absolute oral bioavailability at or above 20%. Isolated low or qualitative 'low bioavailability' records are contradicted by direct absolute measurements in the same or closely related molecules.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement is available for the query molecule; the prediction relies on analogue transfer.",
    "Dose, formulation, and solubility effects are not fully captured; some analogues show saturable or formulation-dependent absorption."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

